# The golden MEI documents committed in spec/fixtures/notation/mei/, each a
# render of a shared fixture, regenerated by `rake mei:golden_fixtures`.
# Between them they carry every criterion the MEI writer meets.
module MEIFixtures
  DIRECTORY = File.expand_path("../fixtures/notation/mei", __dir__)
  KERN_DIRECTORY = File.expand_path("../fixtures/notation/kern", __dir__)

  # Each golden's flow, in concert pitch.
  SOURCES = {
    "fourth_species" => -> { LilyPondFixtures.fourth_species },
    "satb_chorale" => -> { kern("satb_chorale") },
    "piano_splits" => -> { kern("piano_splits") },
    "articulations_ornaments_dynamics" => -> { kern("articulations_ornaments_dynamics") },
    "hairpins" => -> { kern("hairpins") },
    "marked_dal_segno_al_coda" => -> { MuseScoreFixtures.marked_dal_segno_al_coda },
    "marked_da_capo_al_fine" => -> { MuseScoreFixtures.marked_da_capo_al_fine },
    "piano_part_marks" => -> { MuseScoreFixtures.piano_part_marks },
    "cross_staff_piano" => -> { LilyPondFixtures.cross_staff_piano },
    "triplets" => -> { TupletFixtures.triplets },
    "grace_notes_before_downbeat" => -> { TupletFixtures.grace_notes_before_downbeat },
    "two_verses" => -> { MuseScoreFixtures.two_verses },
    "clarinet_changes_transposed" => -> { MuseScoreFixtures.clarinet_changes.flows.first }
  }.freeze

  RENDERS = SOURCES.to_h { |name, source| [name, -> { source.call.to_mei }] }.merge(
    "clarinet_changes_transposed" => -> { MuseScoreFixtures.clarinet_changes.add_layout(concert_pitch: false).to_mei }
  ).freeze

  module_function

  def names
    RENDERS.keys
  end

  def mei(name)
    RENDERS.fetch(name).call
  end

  def source(name)
    SOURCES.fetch(name).call
  end

  def path(name)
    File.join(DIRECTORY, "#{name}.mei")
  end

  # Every ABC, LilyPond, kern, tuplet, hairpin, and MuseScore-render fixture,
  # by name, each built fresh.
  def every_fixture
    lily_pond = Dir[File.join(__dir__, "..", "fixtures", "notation", "lily_pond", "*.ly")].sort.to_h do |path|
      ["lily_pond/#{File.basename(path)}", -> { HeadMusic::Notation::LilyPond.parse(File.read(path)) }]
    end
    abc = %i[SPEED_THE_PLOUGH CHROMATIC_AIR].to_h do |name|
      ["ABCFixtures::#{name}", -> { HeadMusic::Notation::ABC.parse(ABCFixtures.const_get(name)) }]
    end
    renders = MuseScoreFixtures.names.to_h do |name|
      ["MuseScoreFixtures #{name}", -> { HeadMusic::Notation::MusicXML.parse(MuseScoreFixtures.musicxml(name)) }]
    end
    MEIHelpers.sample_flows.merge(lily_pond, abc, renders)
  end

  def kern(name)
    HeadMusic::Notation::Kern.parse(File.read(File.join(KERN_DIRECTORY, "#{name}.krn")))
  end
end
